void mergeSort(vector<int>& a, int l, int r, vector<int>& buf) {
    if (l >= r) return;
    int m = l + (r - l) / 2;
    mergeSort(a, l, m, buf);
    mergeSort(a, m + 1, r, buf);
    int i = l, j = m + 1, k = l;
    while (i <= m && j <= r)
        buf[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];
    while (i <= m) buf[k++] = a[i++];
    while (j <= r) buf[k++] = a[j++];
    for (int t = l; t <= r; ++t) a[t] = buf[t];
}
